
:root{--fv90-coins:url("data:image/png;base64,");--fv90-cash:url("data:image/png;base64,");--fv90-xp:url("data:image/png;base64,");--fv90-logo:url("data:image/png;base64,");--fv90-name:url("data:image/png;base64,");}
/* V90 approved Nostalgia graphics; original game HUD is retained for state updates */
html.mode-farm .top.fv38-hud{visibility:hidden!important;pointer-events:none!important}
#fv90-nostalgia-hud{position:fixed;top:calc(env(safe-area-inset-top) + 5px);left:0;right:0;z-index:22;pointer-events:none;font-family:system-ui,-apple-system,sans-serif;color:#4b2813}
#fv90-nostalgia-hud *{box-sizing:border-box}
#fv90-nostalgia-hud .fv90-bars{position:absolute;left:8px;top:0;display:flex;flex-direction:column;align-items:flex-start;gap:3px;width:min(52vw,232px)}
#fv90-nostalgia-hud .fv90-item{position:relative;flex:none;display:block;width:100%;height:38px;background-repeat:no-repeat;background-size:100% 100%;background-position:center;overflow:visible}
#fv90-nostalgia-hud .fv90-coin{background-image:var(--fv90-coins)}
#fv90-nostalgia-hud .fv90-cash{background-image:var(--fv90-cash)}
#fv90-nostalgia-hud .fv90-xp{background-image:var(--fv90-xp);height:43px}
#fv90-nostalgia-hud .fv90-value{position:absolute;top:29%;bottom:19%;left:32%;right:12%;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:clamp(11px,2.8vw,16px);line-height:1;color:#542b10;text-shadow:0 1px #ffead2;white-space:nowrap}
/* Approved coin PNG contains sample 123,456: make dynamic number legible over sample. */
#fv90-nostalgia-hud .fv90-coin .fv90-value{left:31%;right:12%;top:24%;bottom:18%;border-radius:12px;background:linear-gradient(#fbe3b5,#f7cf9d)}
/* NF Cash PNG has a printed label: live count appears in a small panel over its center. */
#fv90-nostalgia-hud .fv90-cash .fv90-value{left:38%;right:22%;top:24%;bottom:20%;border-radius:9px;background:linear-gradient(#f7dfac,#f0c285);font-size:clamp(10px,2.5vw,14px)}
#fv90-nostalgia-hud .fv90-cash .fv90-value::before{content:'NF ';font-size:.8em;margin-right:3px}
/* Approved XP PNG contains 27 / 46,320 / 54,000: overlay a real level number and progress. */
#fv90-nostalgia-hud .fv90-xp-level{position:absolute;left:10%;top:23%;width:17%;height:55%;display:flex;align-items:center;justify-content:center;background:linear-gradient(#f9d17d,#f4b04b);border-radius:45%;font-size:clamp(11px,2.7vw,15px);font-weight:1000;transform:rotate(-2deg)}
#fv90-nostalgia-hud .fv90-xp-track{position:absolute;left:32%;width:49%;top:29%;height:41%;background:linear-gradient(#ffe4aa,#f5d194);border-radius:100px;overflow:hidden;border:1px solid #b87a24}
#fv90-nostalgia-hud .fv90-xp-fill{position:absolute;inset:0 auto 0 0;width:0%;background:linear-gradient(#fff272,#f3b800);border-radius:100px}
#fv90-nostalgia-hud .fv90-xp-label{position:absolute;inset:0;font-weight:900;font-size:clamp(8px,2vw,11px);line-height:1.1;display:flex;align-items:center;justify-content:center;color:#512911;text-shadow:0 1px #fff4cc;white-space:nowrap}
#fv90-nostalgia-hud .fv90-right{position:absolute;top:0;right:6px;display:flex;align-items:center;flex-direction:column;width:min(39vw,165px);gap:0}
#fv90-nostalgia-hud .fv90-logo{width:100%;height:77px;background-image:var(--fv90-logo);background-size:contain;background-repeat:no-repeat;background-position:center}
#fv90-nostalgia-hud .fv90-name{position:relative;width:100%;height:45px;background-image:var(--fv90-name);background-size:100% 100%;background-repeat:no-repeat}
#fv90-nostalgia-hud .fv90-name-text{position:absolute;left:25%;right:12%;top:19%;bottom:19%;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:clamp(9px,2.6vw,13px);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;text-align:center}
#fv90-nostalgia-hud .fv90-item,#fv90-nostalgia-hud .fv90-logo,#fv90-nostalgia-hud .fv90-name{max-width:none!important}
@media(max-width:350px){#fv90-nostalgia-hud .fv90-bars{width:50vw}#fv90-nostalgia-hud .fv90-right{width:38vw}#fv90-nostalgia-hud .fv90-item{height:34px}#fv90-nostalgia-hud .fv90-xp{height:39px}}
#fv90-hud-size-editor{margin-top:10px;padding:9px;border:2px solid #b68c57;border-radius:9px;background:#fff6db;color:#51361b}
#fv90-hud-size-editor .fv90-size-row{display:grid;grid-template-columns:1.45fr 1fr 1fr;gap:4px;align-items:center;margin:5px 0}
#fv90-hud-size-editor input{width:100%;min-width:0;font-size:14px!important;min-height:34px!important}
#fv90-hud-size-editor button{margin-top:5px;min-height:38px}

